Review this Go message-processing change for distributed correctness. Publish retries at most three times internally; Handle attempts Apply at most three times per delivery; the broker makes at most five total deliveries when a message is not acknowledged. UpdateAggregate is not idempotent. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

func (c *Consumer) Handle(ctx context.Context, message Message) error {
    for attempt := 0; attempt < 3; attempt++ {
        if err := c.service.Apply(ctx, message); err == nil {
            return c.broker.Ack(ctx, message)
        }
    }
    return ErrRetry
}

func (s *Service) Apply(ctx context.Context, message Message) error {
    seen, err := s.inbox.Seen(ctx, message.ID)
    if err != nil { return err }
    if seen { return nil }

    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback()
    if err := UpdateAggregate(ctx, tx, message); err != nil { return err }
    if err := tx.Commit(); err != nil { return err }

    event := Event{ID: uuid.NewString(), MessageID: message.ID}
    if err := s.bus.Publish(ctx, event); err != nil { return err }
    return s.inbox.Record(ctx, message.ID)
}

Review this Go broker-consumer change for distributed correctness. Offsets are ordered within each partition. CommitOffset(partition, n) cumulatively commits every offset at or below n and can return an error after the commit took effect. Each invocation of ApplyRemote makes one initial remote-effect attempt and at most two internal retries, for at most three remote-effect attempts per invocation. A remote-effect attempt may succeed even when its response is lost, and the operation is not idempotent. The loop invokes ApplyRemote at most three times per delivery; the broker makes at most four total deliveries for an uncommitted message. A batch may contain 100,000 messages. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

func (c *Consumer) HandleBatch(ctx context.Context, batch []Message) error {
    var workers sync.WaitGroup
    for _, message := range batch {
        workers.Add(1)
        go func(message Message) {
            defer workers.Done()
            for attempt := 0; attempt < 3; attempt++ {
                if err := c.processor.ApplyRemote(ctx, message); err != nil {
                    continue
                }
                _ = c.broker.CommitOffset(ctx, message.Partition, message.Offset)
                return
            }
        }(message)
    }
    workers.Wait()
    return nil
}

Review this Go shard-worker change for distributed correctness. An acquired lease expires 30 seconds after the most recent renewal that took effect; after expiry, another worker can acquire the shard. Each acquisition returns a strictly increasing fencing token. In the evaluation schedule there are at most two owners: the original owner and one successor, and on takeover the successor receives the same incomplete job. Renew and Release may take effect even when their response is lost and the caller receives an error. Release deletes by shard without comparing the acquired lease identity or fencing token. Each invocation of Remote.Apply makes exactly one remote-effect attempt. Apply is non-idempotent, may take effect even when its response is lost, accepts no fencing token or idempotency key, and provides no status lookup. Store.MarkDone is the authoritative durable completion write and currently accepts no fencing token. The loop invokes Apply at most three times per job for each owner. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

func (w *Worker) Run(ctx context.Context, shard string, jobs []Job) error {
	lease, err := w.leases.Acquire(ctx, shard, 30*time.Second)
	if err != nil {
		return err
	}

	go func() {
		ticker := time.NewTicker(10 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			renewCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			_ = lease.Renew(renewCtx, 30*time.Second)
			cancel()
		}
	}()

	for _, job := range jobs {
		for attempt := 0; attempt < 3; attempt++ {
			if err := w.remote.Apply(ctx, job); err != nil {
				continue
			}
			break
		}
		_ = w.store.MarkDone(ctx, job.ID)
	}

	return lease.Release(ctx)
}
